import { pxToRem } from "../../helpers";
import { buttonReset } from "../Button";
import { StyleFn } from "..";

const transitionDuration = "250ms";
const transitionFunction = "cubic-bezier(0.33, 1, 0.68, 1)";

export const SlideIndicator: StyleFn = (theme, mode) => {
  const { color, size } = theme;

  return {
    root: {
      display: "flex",
      height: "fit-content",
      width: "fit-content",
      gap: size.spacing[8],
      transition: `transform ${transitionDuration} ${transitionFunction}`,
      // Use a transparent border initially to prevent layout shifts.
      border: `2px solid transparent`,
      borderRadius: size.radius[1000],
      "&:focus-visible": {
        outline: "none",
      },
    },
    _vertical: {
      flexDirection: "column",
    },
    container: {
      display: "flex",
      alignItems: "baseline",
      maxWidth: pxToRem(164),
      maxHeight: pxToRem(164),
      overflow: "hidden",
      width: "fit-content",
      "&:has(:focus-visible)": {
        borderRadius: size.radius[1000],
        outline: `2px solid ${color.border.accent.focus[mode]}`,
      },
    },
    step: {
      ...buttonReset,
      position: "relative",
      borderRadius: "50%",
      height: size.spacing[16],
      width: size.spacing[16],
      padding: size.spacing[8],
      cursor: "pointer",
      transition: `all ${transitionDuration} ${transitionFunction}`,
      transitionProperty: "width, height, margin",
      "&:after": {
        backgroundColor: color.surface.componentonbackground.strong[mode],
        padding: size.spacing[4],
        content: "''",
        borderRadius: "50%",
      },
      "&:focus-visible": {
        boxShadow: `inset 0 0 0 2px ${color.border.accent.focus[mode]}`,
      },
    },
    step_beforeend: {
      "&:after": {
        padding: size.spacing[3],
      },
    },
    step_end: {
      "&:after": {
        padding: size.spacing[2],
      },
    },
    step_selected: {
      "&:after": {
        backgroundColor: color.surface.accent.active[mode],
      },
    },
  };
};

